/* state: a guest's progress is kept in this browser; a signed-in user's is saved to
   their account by src/store.js, which also supplies the starting state */
let S=BOB.initialState();
S.lessons=S.lessons||{};S.acts=S.acts||{};S.conf=S.conf||{};
const qcPassed=l=>!!(S.lessons[l.id]&&S.lessons[l.id].best>=75);
/* a lesson is complete only when every task in it is complete: quick check passed (3/4+), key vocab and each activity attempted */
const done=l=>lessonParts(l).parts.every(p=>p.done);
const doneCount=t=>(t.lessons||[]).filter(done).length;
function save(){BOB.save(S)}

const esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const $=s=>document.querySelector(s);
/* A section's status comes from every task in its lessons. Sections without lessons yet fall back to their vocabulary test. */
function secStatus(t){if(t.lessons){const ps=t.lessons.map(lessonParts);return {pct:secOverall(t),started:ps.some(p=>p.started)}}
  const s=S.scores[t.id];return {pct:s?s.best:0,started:!!s}}
const lvOf=(pct,started)=>!started?0:pct>=80?3:pct>=50?2:1;
function level(id){const t=TOPICS.find(x=>x.id===id);if(t){const st=secStatus(t);return lvOf(st.pct,st.started)}
  const s=S.scores[id];return s?lvOf(s.best,true):0}
const LBL=["Not started","Started","Developing","Secure"],CLS=["none","start","dev","sec"];
function chip(id){const t=TOPICS.find(x=>x.id===id),l=level(id);let pct=null;
  if(t){const st=secStatus(t);if(st.started)pct=st.pct}else if(S.scores[id])pct=S.scores[id].best;
  return `<span class="chip ${CLS[l]}"${t?` title="Completion across all tasks in this section"`:""}>${pct!=null?pct+"% · ":""}${LBL[l]}</span>`}
function vchip(id){const s=S.scores[id],l=s?lvOf(s.best,true):0;return `<span class="chip ${CLS[l]}">${s?s.best+"%":"Not started"}</span>`}
function accent(p){return p===1?"--accent:var(--p1);--accent-soft:var(--p1-soft)":"--accent:var(--p2);--accent-soft:var(--p2-soft)"}

function nav(route){
  const on=r=>route===r||route.startsWith(r)?' class="on"':'';
  const t=TOPICS.find(x=>"t-"+x.id===route)||ALL_LESSONS.find(x=>"l-"+x.id===route)?.topic;
  const pp=route==="paper-1"?1:route==="paper-2"?2:t?t.ch.paper:0;
  $("#links").innerHTML=`<a href="#paper-1"${pp===1?' class="on"':''}>Paper 1</a>
  <a href="#paper-2"${pp===2?' class="on"':''}>Paper 2</a>
  <a href="#flashcards"${on("flashcards")}>Flash cards</a>
  <a href="#exams"${on("exam")}>Exam questions</a>
  ${isTeacher()?`<a href="#teacher"${route==="teacher"||route.startsWith("class-")?' class="on"':""}>My classes</a>`:myClass()?`<a href="#todo"${on("todo")}>To-do${todoCount()?` <span class="tbadge" aria-label="${todoCount()} to do">${todoCount()}</span>`:""}</a>`:""}
  ${isTeacher()?"":`<a href="#dashboard"${on("dashboard")}${S.user?"":' title="See example student and teacher dashboards"'}>${S.user?"Dashboard":"Dashboard preview"}</a>`}${S.user?"":`<a href="#pricing"${on("pricing")}>Pricing</a>`}
  ${S.user?(typeof rwNav==="function"?rwNav(route):"")+userMenu(route):`<a href="#login"${on("login")}>Sign in</a><a class="btn primary small" href="#register">Register</a>`}`;
}

/* views */
/* the logo, drawn inline on the home page so its falling bits can move (public/logo.svg, from scripts/logo.py) */
let LOGO_SVG=null;
fetch("/logo.svg").then(r=>r.ok?r.text():null).then(t=>{if(t&&t.includes("<svg")){LOGO_SVG=t;document.querySelectorAll(".herologo img").forEach(i=>i.outerHTML=t)}}).catch(()=>{});
function home(){
  const b="01100010";
  const rows=[["'b'",b],["0x62","01100010"],["98",b]];
  return `<section class="hero">
   <div>
    <div class="eyebrow">Cambridge IGCSE Computer Science · 0478</div>
    <h1 style="margin-top:10px">Every syllabus point, one byte at a time.</h1>
    <p class="hcover"><span class="hcbadge" aria-hidden="true">✓</span><span><b>Full coverage of the Cambridge IGCSE Computer Science (0478) syllabus</b> for exams in 2026, 2027 and 2028: every section of Paper 1 and Paper 2.</span></p>
    <p class="lead">Notes, key vocabulary and self-tests for every topic in Paper 1 and Paper 2, with a dashboard that shows students and teachers exactly what is secure and what needs work.</p>
    <div class="ctas">${homeCtas()}</div>
   </div>
   <div class="herologo">${LOGO_SVG||'<img src="/logo.svg" alt="Bits of Bytes logo">'}</div>
  </section>
  ${homeCoverage()}
  <section class="papers">${[1,2].map(p=>{const P=PAPERS[p],cs=CH.filter(c=>c.paper===p);return `<a class="paper p${p}" href="#paper-${p}">
    <span class="tag">${P.code}</span><h2>${P.title}</h2><p style="color:var(--muted)">${P.blurb}</p>
    <ol start="${cs[0].n}">${cs.map(c=>`<li>${c.title}</li>`).join("")}</ol>
    <span class="meta">${P.facts.slice(0,3).join(" · ")}</span></a>`}).join("")}</section>
  <section class="section"><div class="eyebrow">How it works</div>
   <div class="feats">
    <div class="feat"><span class="k">Learn</span><h3>Short lessons for every syllabus point</h3><p>Each section is split into short lessons, with theory, a hands-on practice tool and a quick check at the end.</p></div>
    <div class="feat"><span class="k">Test</span><h3>Key vocabulary self-tests</h3><p>Every page has an interactive vocabulary box. Read the terms, then test yourself and get a score.</p></div>
    <div class="feat"><span class="k">Track</span><h3>A dashboard that is your home screen</h3><p>Scores feed straight into your dashboard so you can see which topics are secure and which to revisit.</p></div>
   </div></section>
  ${homeAudience()}`;
}

function paper(p){
  const P=PAPERS[p],cs=CH.filter(c=>c.paper===p);
  return `<div style="${accent(p)}">
  <div class="crumbs"><a href="#home">Home</a><span>/</span><span>${P.code}</span></div>
  <div class="phead"><div class="eyebrow">${P.code}</div><h1>${P.title}</h1><p>${P.blurb}</p><div class="facts">${P.facts.map(f=>`<span class="fact">${f}</span>`).join("")}</div></div>
  ${cs.map(c=>`<div class="chapter"><div><div class="n">${c.n}</div><h2>${c.title}</h2></div>
   <div class="tlist">${c.topics.map(t=>`<a class="tcard" href="#t-${t.id}"><div class="top"><span class="code">${t.code}</span>${chip(t.id)}</div><h3>${t.title}</h3><small>${t.lessons?`${doneCount(t)} of ${t.lessons.length} lessons complete · `:""}${t.v.length} key terms</small></a>`).join("")}</div></div>`).join("")}
  </div>`;
}

function topic(t){
  const i=TOPICS.indexOf(t),prev=TOPICS[i-1],next=TOPICS[i+1],p=t.ch.paper;
  const chTitle=t.ch.topics.length>1?`<span>/</span><span>${t.ch.n} ${t.ch.title}</span>`:"";
  return `<div style="${accent(p)}">
  <div class="crumbs"><a href="#home">Home</a><span>/</span><a href="#paper-${p}">${PAPERS[p].code}</a>${chTitle}</div>
  <div class="phead"><h1><span class="code">${t.code}</span>${t.title}</h1></div>
  <div class="topic">
   <div>
    <div class="block goals"><div class="eyebrow">By the end of this section you should be able to</div><ul class="obj${t.lessons?" num":""}">${t.obj.map((o,i)=>`<li${t.lessons?` data-n="${t.code}.${i+1}"`:""}>${esc(o)}</li>`).join("")}</ul></div>
    ${t.lessons?`<div class="block"><div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px"><div class="eyebrow">Lessons</div><span class="prog">${doneCount(t)} of ${t.lessons.length} complete</span></div>
     <ol class="steps">${t.lessons.map(l=>`<li class="step${done(l)?" done":""}"><a href="#l-${l.id}"><span class="dot">${done(l)?"✓":l.n}</span><span><b>${l.title}</b><span class="covers">${l.covers.map(c=>`<span>${t.code}.${c}</span>`).join("")}${l.tool?`<span class="ctask">Practice tool</span>`:""}${l.v?`<span class="ctask">Key vocab${S.scores["lv-"+l.id]?`: ${S.scores["lv-"+l.id].best}%`:""}</span>`:""}${(l.acts||[]).map(a=>{const s=S.acts[l.id+"-"+a.id];return `<span class="ctask">${a.title}${s&&s.hist?`: ${Math.round(s.correct/s.total*100)}%`:""}</span>`}).join("")}</span></span>${lchip(l)}</a></li>`).join("")}</ol>
     <p class="vfoot">A lesson is complete when you've passed its quick check and tried its key vocabulary test and every activity.</p></div>`
    :`<div class="block"><div class="eyebrow">Lessons</div><div class="placeholder"><h3>Lessons coming soon</h3><p>This section will be split into short lessons, each with theory, practice and a quick check.</p></div></div>`}
    <nav class="pager">${prev?`<a href="#t-${prev.id}"><small>← Previous · ${prev.code}</small><b>${prev.title}</b></a>`:""}${next?`<a class="next" href="#t-${next.id}"><small>Next · ${next.code} →</small><b>${next.title}</b></a>`:""}</nav>
   </div>
   ${t.lessons?`<aside class="vocab secp" id="secp" aria-label="This section">${secPanel(t)}</aside>`:`<aside class="vocab" id="vocab"></aside>`}
  </div></div>`;
}

/* the section page's side panel: progress, where to pick up, and practice for just this section.
   (Each lesson has its own key vocabulary test, so the section no longer has one.) */
function secPanel(t){const p=t.ch.paper,lids=t.lessons.map(l=>l.id),teach=isTeacher();
  const nEx=exPool(lids).length,nFc=fcPool(lids,"pre").length;
  let top="";
  if(!teach){const st=secStatus(t),lv=lvOf(st.pct,st.started),nd=doneCount(t),nx=t.lessons.find(l=>!done(l));
    top=`<div class="secst"><div class="stat">${st.pct}<small>%</small></div><span class="sub">across every task in this section's lessons</span></div>
    <div class="bar"><i style="width:${st.pct}%"></i></div>
    <p class="sub" style="margin:0">${nd} of ${t.lessons.length} lessons complete</p>
    ${nx?`<a class="btn primary secnext" href="#l-${nx.id}"><small>${nd||st.started?"Next up":"Start here"} · Lesson ${nx.n}</small><b>${esc(nx.title)}</b></a>`
      :`<p class="secdone">✓ Every lesson in this section is complete. Keep it fresh with the practice below.</p>`}`}
  const prac=[nEx?`<a class="seclink" href="#exams" data-secex="${t.id}"><b>Past paper questions</b><small>${plural(nEx,"question")} on this section</small></a>`:"",
    nFc?`<a class="seclink" href="#flashcards" data-secfc="${t.id}"><b>Flash cards</b><small>${plural(nFc,"card")} on this section</small></a>`:""].join("");
  let hw="";
  if(teach){const cls=tClasses(S.user.id);
    hw=`<div class="secblk"><span class="eyebrow">Set as homework</span>${cls.length?`
     ${cls.length>1?`<label class="sub">Class <select id="sechwcls">${cls.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select></label>`:`<span class="sub">For ${esc(cls[0].name)}</span>`}
     <div class="tbb"><button class="btn small" data-sethw="lessons" data-t="${t.id}" data-cls="${cls[0].id}">The ${plural(t.lessons.length,"lesson")}</button>${nEx?`<button class="btn small" data-sethw="exam" data-t="${t.id}" data-cls="${cls[0].id}">Exam questions</button>`:""}</div>`
     :`<span class="sub">Create a class in <a href="#teacher">My classes</a> first.</span>`}</div>`}
  return `<div class="vhead"><h3>This section</h3>${teach?"":`<span class="chip ${CLS[lvOf(secStatus(t).pct,secStatus(t).started)]}">${LBL[lvOf(secStatus(t).pct,secStatus(t).started)]}</span>`}</div>
  <div class="vbody">${top}${prac?`<div class="secblk"><span class="eyebrow">Practise this section</span>${prac}</div>`:""}${hw}</div>`}
document.addEventListener("click",e=>{const b=e.target.closest("[data-secex],[data-secfc],[data-sethw]");if(!b)return;
  if(b.dataset.secex){const t=TOPICS.find(x=>x.id===b.dataset.secex),p=t.ch.paper;EX.paper=p;S.exPaper=p;EX.sel[p]=new Set(t.lessons.map(l=>l.id).filter(id=>exPool([id]).length));EX.mode="setup";return}
  if(b.dataset.secfc){const t=TOPICS.find(x=>x.id===b.dataset.secfc);FCPAGE.sel=new Set(t.lessons.map(l=>l.id));return}
  const t=TOPICS.find(x=>x.id===b.dataset.t),sel=$("#sechwcls"),cid=sel?sel.value:b.dataset.cls,k=b.dataset.sethw;
  TV.form={...newForm(),kind:k,title:`${t.code} ${t.title}${k==="exam"?": exam questions":""}`,lessons:k==="lessons"?t.lessons.map(l=>l.id):[],papers:[t.ch.paper],topics:[t.id]};
  TV.tab="assign";TV.newOpen=true;TV.spring=true;location.hash="class-"+cid});

/* lesson pages */
function lchip(l){const lp=lessonParts(l),n=lp.parts.filter(p=>p.done).length,t=lp.parts.length;
  if(!lp.started)return `<span class="chip none">Not started · 0/${t} tasks</span>`;
  return n===t?`<span class="chip sec">Complete · ${lp.overall}%</span>`:`<span class="chip ${n?"dev":"start"}">${n}/${t} tasks · ${lp.overall}%</span>`}
function qchip(l){const s=S.lessons[l.id];if(!s)return `<span class="chip none">Not started</span>`;return qcPassed(l)?`<span class="chip sec">Passed · ${s.best}%</span>`:`<span class="chip start">Best ${s.best}%</span>`}
let TAB="theory",LQ=null;
function lesson(l){
  const t=l.topic,p=t.ch.paper,ls=t.lessons,prev=ls[l.n-2],next=ls[l.n];
  const tabbed=!!l.tool;
  return `<div style="${accent(p)}">
  <div class="crumbs"><a href="#home">Home</a><span>/</span><a href="#paper-${p}">${PAPERS[p].code}</a><span>/</span><a href="#t-${t.id}">${t.code} ${t.title}</a></div>
  <div class="lhead"><div class="eyebrow">${t.code} · Lesson ${l.n} of ${ls.length}</div><h1>${l.title}</h1>
   <div class="stepper">${ls.map(x=>`<a href="#l-${x.id}" class="${done(x)?"done":""}${x===l?" here":""}" aria-label="Lesson ${x.n}: ${esc(x.title)}${done(x)?" (complete)":""}" title="${x.n}. ${esc(x.title)}"></a>`).join("")}</div>
   <div class="covers">${l.covers.map(c=>`<span>Syllabus ${t.code}.${c}</span>`).join("")}</div></div>
  <div class="lesson"><div class="sheet">
   ${tabbed?`<div class="tabs" role="tablist"><button role="tab" id="tab-theory" data-tab="theory" aria-selected="${TAB==="theory"}">Theory</button><button role="tab" id="tab-practice" data-tab="practice" aria-selected="${TAB==="practice"}">Practice</button></div>`:""}
   <div id="pane-theory"${tabbed&&TAB==="practice"?" hidden":""}>
    ${(tpl=>tpl?tpl.innerHTML:"")(document.getElementById("th-"+l.id))}
    <div class="placeholder"${document.getElementById("th-"+l.id)?" hidden":""}><h3>Theory goes here</h3><p>Send me the content for “${esc(l.title)}” from your old site and I'll write it up here, with explanations, worked examples and diagrams.</p>
    <ul class="obj" style="margin-top:8px">${l.covers.map(c=>`<li>${esc(t.obj[c-1]||"")}</li>`).join("")}</ul></div>
    ${tabbed&&!document.getElementById("th-"+l.id)?`<p class="vfoot" style="margin-top:12px">Try it out on the <a href="#l-${l.id}" data-tab="practice">Practice</a> tab.</p>`:""}
   </div>
   ${tabbed?`<div id="pane-practice"${TAB!=="practice"?" hidden":""}><div class="tool" id="tool"></div></div>`:""}
   <div style="margin-top:28px">${next?"":`<div class="endcta" style="margin-bottom:18px"><span><b>That's the last lesson in ${t.code}.</b> See how the whole section is going, and practise it.</span><a class="btn primary small" href="#t-${t.id}">Back to ${t.code}</a></div>`}
   <nav class="pager">${prev?`<a href="#l-${prev.id}"><small>← Lesson ${prev.n}</small><b>${prev.title}</b></a>`:`<a href="#t-${t.id}"><small>← Section overview</small><b>${t.code} ${t.title}</b></a>`}${next?`<a class="next" href="#l-${next.id}"><small>Lesson ${next.n} →</small><b>${next.title}</b></a>`:""}</nav></div>
  </div>
  <aside class="lside multi grouped">
   ${sbSec("check",l.v?"Quick check and vocab":"Quick check",`<div class="check" id="lcheck"></div>${l.v?`<div class="check" id="vocab"></div>`:""}`)}
   ${(l.acts||[]).length?sbSec("acts","Activities",(l.acts||[]).map(a=>`<div class="check" id="act-${a.id}"></div>`).join("")):""}
   ${sbSec("rev","Revision",`<div class="check" id="fclesson" data-fcw="l-${l.id}"></div><div class="check" id="exlesson"></div>`)}
   ${sbSec("tz","Puzzles",`<div class="check" id="tzcard"></div>`)}</aside></div></div>`;
}

/* the lesson sidebar: four foldable groups (quick check and vocab, activities, revision, puzzles).
   One group is open at a time; each header shows how far the student has got. */
const SBOPEN={};
/* every page load starts with all groups closed */
addEventListener("hashchange",()=>{for(const k in SBOPEN)delete SBOPEN[k]});
/* inside a group each card is a one-line row; tapping it opens the card full screen, where it's used */
function cardMeta(l,id){const pl=(n,w)=>`${n} ${w}${n===1?"":"s"}`;
  if(id==="lcheck"){const s=S.lessons[l.id],ok=qcPassed(l);return {st:ok?"ok":s?"part":"",t:s?`${ok?"Passed":"Not passed yet"} · best ${s.best}%`:"Not started"}}
  if(id==="vocab"){const v=S.scores["lv-"+l.id];return {st:v?"ok":"",t:v?`Done · best ${v.best}%`:"Not started"}}
  if(id.startsWith("act-")){const s=actStats(S.acts[l.id+"-"+id.slice(4)]);return {st:s?"ok":"",t:s?`Done · ${Math.round(s.correct/s.total*100)}% overall · ${pl(s.attempts,"try")}`.replace("trys","tries"):"Not started"}}
  if(id==="fclesson"){const f=S.fcs[l.id];return {st:f?"ok":"fo",t:f?`Best ${f.best}% · ${pl(f.rounds,"round")}`:"Optional practice"}}
  if(id==="exlesson"){const st=exLessonStats([l.id]);return {st:st.n&&st.att===st.n?"ok":st.att?"part":"fo",t:st.att?`${st.att} of ${st.n} tried · ${st.b}/${st.m} marks`:`${pl(st.n,"question")} · optional`}}
  return {st:"",t:""}}
const SB_X=`<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>`;
function cardDecorate(el,l){const h=el.querySelector(":scope > .vhead");if(!h)return;const big=el.classList.contains("focus");
  if(big&&!h.querySelector('[data-act="afocus"],[data-fclose]'))h.insertAdjacentHTML("beforeend",`<button class="iconbtn fclose" data-fclose aria-label="Close full screen view" title="Close">${SB_X}</button>`);
  if(!big)h.querySelector("[data-fclose]")?.remove();
  if(big){h.removeAttribute("role");h.removeAttribute("tabindex");h.removeAttribute("aria-expanded")}else{h.setAttribute("role","button");h.tabIndex=0;h.setAttribute("aria-expanded","false")}
  const h3=h.querySelector("h3");if(!h3)return;const m=cardMeta(l,el.id),html=`<i class="fdot ${m.st}" aria-hidden="true">${m.st==="ok"?"✓":""}</i>${esc(m.t)}`;
  let f=h3.querySelector(".fsum");if(!f){f=document.createElement("small");f.className="fsum";h3.append(f)}if(f.innerHTML!==html)f.innerHTML=html}
function cardOpen(el,l){if(el.classList.contains("focus"))return;const ib=el.querySelector(':scope > .vhead [data-act="afocus"]');
  if(ib)ib.click();else setFocus(el);cardDecorate(el,l);
  const f=el.querySelector('.vbody button:not([disabled]),.vbody input,[data-fclose],[data-act="afocus"]');if(f)f.focus({preventScroll:true})}
const sbSec=(k,title,body)=>`<section class="lgrp" data-lg="${k}"><button type="button" class="lghead" data-lgt="${k}" aria-expanded="false"><span><b>${title}</b><small class="lgsum"></small></span><i class="fdot" aria-hidden="true"></i></button><div class="lgbody" hidden>${body}</div></section>`;
function sbMeta(l,k){const pl=(n,w)=>`${n} ${w}${n===1?"":"s"}`;
  if(k==="check"){const q=S.lessons[l.id],ok=qcPassed(l),v=l.v?S.scores["lv-"+l.id]:null,need=l.v?2:1,n=(ok?1:0)+(v?1:0);
    return {st:n===need?"ok":q||v?"part":"",t:n===need?`Done · quick check ${q.best}%${v?` · vocab ${v.best}%`:""}`:q||v?`${n} of ${need} done${q?` · quick check best ${q.best}%`:""}`:"Needed to complete the lesson"}}
  if(k==="acts"){const as=l.acts||[],n=as.filter(a=>actStats(S.acts[l.id+"-"+a.id])).length;
    return {st:n===as.length?"ok":n?"part":"",t:n===as.length?`All ${as.length} done`:n?`${n} of ${as.length} done`:`${as.length} activit${as.length===1?"y":"ies"} · needed to complete the lesson`}}
  if(k==="rev"){const f=S.fcs[l.id],e=exLessonStats([l.id]);
    return {st:"fo",t:[f?`flash cards best ${f.best}%`:"",e.att?`${e.att}/${e.n} exam questions`:""].filter(Boolean).join(" · ")||`Flash cards${e.n?" and exam questions":""} · optional`}}
  if(k==="tz")return {st:tzDone(l.id)?"ok":"fo",t:tzDone(l.id)?`Solved · best ${tzBest(l.id)}%`:"Tarsia puzzle · bonus points"};
  return {st:"",t:""}}
function sbDraw(l){const side=$(".lside.grouped");if(!side)return;
  side.querySelectorAll(".lgrp").forEach(g=>{const k=g.dataset.lg,open=SBOPEN[l.id]===k,m=sbMeta(l,k),h=g.querySelector(".lghead");
    g.classList.toggle("open",open);g.querySelector(".lgbody").hidden=!open;h.setAttribute("aria-expanded",String(open));
    /* only touch what changed, so the watcher below doesn't fire again */
    const sm=g.querySelector(".lgsum"),d=h.querySelector(".fdot"),tk=m.st==="ok"?"✓":"";
    if(sm.textContent!==m.t)sm.textContent=m.t;if(d.className!=="fdot "+m.st)d.className="fdot "+m.st;if(d.textContent!==tk)d.textContent=tk});
  side.querySelectorAll(".check.compact").forEach(el=>cardDecorate(el,l))}
function foldInit(l){const side=$(".lside.grouped");if(!side)return;
  if(!side.querySelector(":scope > .lstitle"))side.insertAdjacentHTML("afterbegin",`<h2 class="lstitle">Lesson activities</h2>`);
  side.querySelectorAll(".check:not(#tzcard)").forEach(el=>{el.classList.add("compact");
    new MutationObserver(()=>cardDecorate(el,l)).observe(el,{childList:true});
    el.addEventListener("click",e=>{if(el.classList.contains("focus")||e.target.closest('a,input,select,label,[data-fclose],[data-act="afocus"]'))return;
      if(e.target.closest("button")&&!e.target.closest(".vhead"))return;e.preventDefault();e.stopPropagation();cardOpen(el,l)},true);
    el.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.classList.contains("vhead")&&!el.classList.contains("focus")){e.preventDefault();cardOpen(el,l)}})});
  if(!(l.id in SBOPEN))SBOPEN[l.id]=null;
  side.addEventListener("click",e=>{const h=e.target.closest("[data-lgt]");if(!h)return;const k=h.dataset.lgt;
    SBOPEN[l.id]=SBOPEN[l.id]===k?null:k;sbDraw(l);
    if(SBOPEN[l.id]){const g=h.closest(".lgrp");requestAnimationFrame(()=>{const r=g.getBoundingClientRect();if(r.top<70||r.top>innerHeight*.6)g.scrollIntoView({block:"nearest",behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})})}});
  /* keep the summaries up to date as results come in */
  new MutationObserver(()=>{clearTimeout(side._lg);side._lg=setTimeout(()=>sbDraw(l),60)}).observe(side,{childList:true,subtree:true});
  sbDraw(l)}
function lcheck(l){
  const el=$("#lcheck");if(!el)return;const s=S.lessons[l.id];let body;
  const next=l.topic.lessons[l.n];
  if(!LQ||LQ.id!==l.id){
    body=`<p>${l.q.length} questions on this lesson. Score 3 or more to pass. To complete the lesson, also do the key vocabulary test and any activities.</p>
    <button class="btn primary" data-act="lstart">Start quick check</button>
    <p class="vfoot">${s?`Best ${s.best}% · last ${s.last}% · ${s.attempts} attempt${s.attempts>1?"s":""}`:"No attempts yet"}</p>`;
  }else if(LQ.k<LQ.items.length){
    const it=LQ.items[LQ.k];
    body=`<div class="qmeta"><span>Question ${LQ.k+1} of ${LQ.items.length}</span><span>Score ${LQ.right}</span></div>
    <div class="bar"><i style="width:${LQ.k/LQ.items.length*100}%"></i></div>
    <p class="qdef">${esc(it.q)}</p>
    <div class="opts">${it.opts.map((o,i)=>{let c="opt";if(LQ.picked!=null){if(o===it.a)c+=" right";else if(i===LQ.picked)c+=" wrong"}return `<button class="${c}" data-act="lpick" data-i="${i}"${LQ.picked!=null?" disabled":""}>${esc(o)}</button>`}).join("")}</div>
    ${LQ.picked!=null?`<button class="btn primary" data-act="lnext">${LQ.k+1<LQ.items.length?"Next question":"See my score"}</button>`:""}`;
  }else{
    const pct=Math.round(LQ.right/LQ.items.length*100),ok=pct>=75;
    body=`<div class="result"><div class="big">${LQ.right}/${LQ.items.length}</div><b>${ok?"Quick check passed":"Not quite there yet"}</b>
    <p>${ok?(S.user?"Saved to your dashboard.":"Saved in this browser. <a href=\"#register\">Register</a> to keep your progress."):"Have another look at the theory and try again. You need 3 out of 4."}</p></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-act="lstart">Try again</button></div>`;
  }
  el.innerHTML=`<div class="vhead"><h3>Quick check</h3>${qchip(l)}</div><div class="vbody">${body}</div>`;
}
