GEN.conv=function(){const qs=[],used=new Set(),R=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
  const plan={bd:[[2,10,8,255],[10,2,8,255],[2,10,8,255],[10,2,8,255],[2,10,64,255],[10,2,64,255],[2,10,256,4095],[10,2,256,1023]],
    dh:[[10,16,10,63],[10,16,16,255],[10,16,16,255],[10,16,100,255],[10,16,160,255],[10,16,256,999],[10,16,256,4095],[10,16,1000,4095]],
    hd:[[16,10,16,255],[16,10,16,255],[16,10,160,255],[16,10,160,255],[16,10,26,255],[16,10,256,4095],[16,10,256,4095],[16,10,4096,65535]]}[this.mode];
  for(const [from,to,lo,hi] of plan){let v,tries=0;
    do{v=R(lo,hi);tries++}while((used.has(v)||((from===16||to===16)&&!/[A-F]/.test(v.toString(16).toUpperCase())&&tries<40))&&tries<200);
    used.add(v);qs.push({from,to,v})}
  return this.mode==="bd"?shuffle(qs.slice(0,6)).concat(qs.slice(6)):qs};
function convWorking(q){const v=q.v;
  if(q.from===2||q.to===2){const b=v.toString(2),pv=[...b].map((c,i)=>c==="1"?2**(b.length-1-i):0).filter(Boolean);return `${pv.join(" + ")} = ${v}`}
  const h=v.toString(16).toUpperCase(),parts=[...h].map((c,i)=>`${c}${/[A-F]/.test(c)?"("+parseInt(c,16)+")":""} × ${16**(h.length-1-i)}`);
  return `${parts.join(" + ")} = ${v}`}
