function makeBitmap(name){const D=DESIGNS[name],n=2**D.d,h=D.rows.length,w=D.rows[0].length;
  // random code for each colour, so the binary is different every time
  const codes=shuffle([...Array(n).keys()]);
  let colours;if(D.d===1)colours=Math.random()<.5?PAL1:[PAL1[0],["Navy","#1F3A80"]];
  else{const h=PALETTE_HINT[name];colours=[["White","#FFFFFF"],[h[1][1],h[1][0]],[h[2][1],h[2][0]],[h[3][1],h[3][0]]]}
  const pix=[];D.rows.forEach(r=>[...r].forEach(c=>pix.push(codes[+c])));
  const key=[...Array(n).keys()].map(code=>{const orig=codes.indexOf(code);return {code,bin:code.toString(2).padStart(D.d,"0"),name:colours[orig][0],hex:colours[orig][1]}});
  return {kind:"paint",name,d:D.d,w,h,pix,key}}
