  Object.entries(ms).forEach(([s,a])=>{const sy=src(s)[1],mx=Math.max(...a);[...new Set(a)].forEach(m=>{if(m<mx||a.filter(x=>x===m).length>1)W+=`<circle class="lgdot${on(s)}" cx="${m}" cy="${sy}" r="4"/>`})});
