  const I=hide?C.in.map(([n,x,y])=>`<path class="lgw" d="M${x+2} ${y}H${x+13}"/><circle class="lgterm" cx="${x+2}" cy="${y}" r="3.5"/><text class="lgname" x="${x-7}" y="${y+5}" text-anchor="end">${n}</text>`).join(""):C.in.map(([n,x,y])=>`<g class="lgin${!hide&&v[n]?" on":""}${o.click?" click":""}"${o.click?` data-lgin="${n}" role="button" tabindex="0" aria-label="Input ${n} is ${v[n]}. Select to change it."`:""}><rect x="${x-13}" y="${y-11}" width="26" height="22" rx="6"/><text x="${x}" y="${y+5}" text-anchor="middle">${hide?"":v[n]}</text></g><text class="lgname" x="${x-19}" y="${y+5}" text-anchor="end">${n}</text>`).join("");
