const LG_INFO={
 AND:{rule:"The output is 1 only when input A <b>and</b> input B are both 1. If either input is 0, the output is 0.",st:"X = A AND B",ex:"🔐 A safe with two keys only opens when key 1 AND key 2 are both turned.",look:"AND has a flat back and a rounded front, like a capital D."},
 OR:{rule:"The output is 1 when input A <b>or</b> input B is 1, or both are. It's only 0 when both inputs are 0.",st:"X = A OR B",ex:"📱 A phone unlocks with a recognised fingerprint OR the correct PIN.",look:"OR has a curved back and comes to a point at the front."},
 NOT:{rule:"NOT has only <b>one</b> input. It flips the input: 1 becomes 0, and 0 becomes 1.",st:"X = NOT A",ex:"🚨 A security beam: when the beam is NOT detected (someone has walked through it), the alarm sounds.",look:"NOT is a triangle with a small circle on its output."},
 NAND:{rule:"NAND means NOT AND. It gives the opposite of an AND gate: the output is 0 only when both inputs are 1. Otherwise it's 1.",st:"X = NOT (A AND B)",ex:"🚗 A warning light stays on unless the driver's seatbelt AND the passenger's seatbelt are both fastened.",look:"NAND is an AND gate with a small circle on its output.",watch:"Don't miss the small circle! It's the only thing that makes this different from an AND gate."},
 NOR:{rule:"NOR means NOT OR. It gives the opposite of an OR gate: the output is 1 only when both inputs are 0.",st:"X = NOT (A OR B)",ex:"🔥 A heater only runs when neither the window NOR the door is open.",look:"NOR is an OR gate with a small circle on its output.",watch:"Don't miss the small circle! It's the only thing that makes this different from an OR gate."},
 XOR:{rule:"XOR means exclusive OR. The output is 1 when the inputs are <b>different</b>. If they're the same (both 0 or both 1), the output is 0.",st:"X = A XOR B",ex:"💡 A landing light with a switch at the top and the bottom of the stairs: flicking either switch changes the light.",look:"XOR is an OR gate with an extra curved line across its inputs.",watch:"Look for the extra curved line by the inputs. Without it, this would be an OR gate."}};

