/* ---------- generators ---------- */
const dbR=a=>a[Math.floor(Math.random()*a.length)],uq=a=>[...new Set(a)];
const DBQ1=[()=>{const c=dbR(["Brown","Black","White"]);return [`Show the Name and Breed of every dog that is ${c}.`,`SELECT Name, Breed FROM Dogs WHERE Colour = '${c}'`]},
 ()=>{const n=dbR([3,4,5]);return [`Show all the fields for dogs that are ${n} years old or older.`,`SELECT * FROM Dogs WHERE Age >= ${n}`]},
 ()=>{const n=dbR([3,4,5]);return [`Show the Name and Age of every dog younger than ${n}.`,`SELECT Name, Age FROM Dogs WHERE Age < ${n}`]},
 ()=>{const b=dbR(["Beagle","Poodle","Labrador","Boxer"]),g=dbR([["M","male"],["F","female"]]);return [`Show the Name of every ${g[1]} ${b}. (Gender is stored as M or F.)`,`SELECT Name FROM Dogs WHERE Breed = '${b}' AND Gender = '${g[0]}'`]},
 ()=>["Show the Name and Breed of every dog that has not been vaccinated.","SELECT Name, Breed FROM Dogs WHERE Vaccinated = FALSE"],
 ()=>{const t=dbR(["Riverton","Hillside","Westbrook"]);return [`Show the FirstName and Surname of every member who lives in ${t}.`,`SELECT FirstName, Surname FROM Members WHERE Town = '${t}'`]},
 ()=>{const l=dbR(["Gold","Silver","Bronze"]);return [`Show the MemberID and FirstName of every member who isn't a ${l} member.`,`SELECT MemberID, FirstName FROM Members WHERE Level <> '${l}'`]},
 ()=>{const p=dbR([0.5,1,2]);return [`Show the Product and Price of every product that costs more than £${p.toFixed(2)}.`,`SELECT Product, Price FROM Products WHERE Price > ${p}`]},
 ()=>{const c=dbR(["Fruit","Dairy","Bakery"]);return [`Show the Product name of every ${c} product that is on sale.`,`SELECT Product FROM Products WHERE Category = '${c}' AND OnSale = TRUE`]},
 ()=>{const a=dbR(["Fruit","Dairy","Bakery"]),b=dbR(["Fruit","Dairy","Bakery"].filter(x=>x!==a));return [`Show all the fields for products in the ${a} or ${b} categories.`,`SELECT * FROM Products WHERE Category = '${a}' OR Category = '${b}'`]}];
const DBQ2=[()=>["Show the Name and Age of every dog, from oldest to youngest.","SELECT Name, Age FROM Dogs ORDER BY Age DESC"],
 ()=>{const c=dbR(["Fruit","Dairy","Bakery"]);return [`Show the Product and Price of every ${c} product, cheapest first.`,`SELECT Product, Price FROM Products WHERE Category = '${c}' ORDER BY Price ASC`]},
 ()=>["Show the FirstName and Surname of every member, in alphabetical order of FirstName.","SELECT FirstName, Surname FROM Members ORDER BY FirstName ASC"],
 ()=>{const t=dbR(["Riverton","Hillside","Westbrook"]);return [`Show the FirstName and Age of every member in ${t}, youngest first.`,`SELECT FirstName, Age FROM Members WHERE Town = '${t}' ORDER BY Age ASC`]},
 ()=>{const b=dbR(["Beagle","Poodle","Labrador","Boxer"]);return [`Count how many dogs are ${b}s.`,`SELECT COUNT(DogID) FROM Dogs WHERE Breed = '${b}'`]},
 ()=>{const t=dbR(["Riverton","Hillside","Westbrook"]);return [`Count how many members live in ${t}.`,`SELECT COUNT(MemberID) FROM Members WHERE Town = '${t}'`]},
 ()=>{const c=dbR(["Fruit","Dairy","Bakery"]);return [`Find the total Stock of all the ${c} products.`,`SELECT SUM(Stock) FROM Products WHERE Category = '${c}'`]},
 ()=>["Find the total Stock of every product that is on sale.","SELECT SUM(Stock) FROM Products WHERE OnSale = TRUE"],
 ()=>{const n=dbR([3,4,5]);return [`Count how many dogs are older than ${n}.`,`SELECT COUNT(DogID) FROM Dogs WHERE Age > ${n}`]}];
const dbTbl=q=>(q.match(/FROM\s+(\w+)/i)||[])[1];
function dbSameResult(given,model){let A,B;try{B=sqlRun(model)}catch(e){return [false,"model"]}try{A=sqlRun(given)}catch(e){return [false,String(e)]}
  if(B.agg){if(!A.agg)return [false,`The task wants a single total or count, so use ${/COUNT/i.test(model)?"COUNT":"SUM"}.`];return [JSON.stringify(A.rows)===JSON.stringify(B.rows),`Your query gives ${A.rows[0].map((v,i)=>sqlFmt(v,A.types[i])).join(", ")}, but the answer is ${B.rows[0].map((v,i)=>sqlFmt(v,B.types[i])).join(", ")}.`]}
  if(A.agg)return [false,"This task doesn't need SUM or COUNT."];
  const lc=a=>a.map(x=>x.toLowerCase());if(lc(A.cols).slice().sort().join()!==lc(B.cols).slice().sort().join())return [false,`Your query shows the field${A.cols.length>1?"s":""} ${A.cols.join(", ")}, but the task asks for ${B.cols.join(", ")}.`];
  const map=lc(B.cols).map(c=>lc(A.cols).indexOf(c)),ra=A.rows.map(r=>JSON.stringify(map.map(i=>r[i]))),rb=B.rows.map(r=>JSON.stringify(r));
  if(B.Q.order.length){if(ra.join()===rb.join())return [true];return [false,ra.slice().sort().join()===rb.slice().sort().join()?"You've found the right records, but they're not in the right order.":`Your query finds ${ra.length} record${ra.length===1?"":"s"}, but it should find ${rb.length}${ra.length===rb.length?" different ones":""}.`]}
  return [ra.slice().sort().join()===rb.slice().sort().join(),`Your query finds ${ra.length} record${ra.length===1?"":"s"}, but it should find ${rb.length}${ra.length===rb.length?". Some of them are different":""}.`]}
function dbW(list){return shuffle(list).slice(0,5).map(f=>{const [task,model]=f();return {kind:"sqlw",task,model,tb:dbTbl(model)}})}
GEN.sqlw1=function(){return dbW(DBQ1)};
GEN.sqlw2=function(){return dbW(DBQ2)};
GEN.sqlout=function(){const all=[...DBQ1,...DBQ2];return shuffle(all).slice(0,6).map(f=>{const [,model]=f(),R=sqlRun(model),tb=dbTbl(model);
  if(R.agg){const a=sqlFmt(R.rows[0][0],R.types[0]),n=+R.rows[0][0],w=uq([n+1,Math.max(0,n-1),n+2,n*2,n+10].filter(x=>x!==n&&x>=0)).slice(0,3).map(x=>sqlFmt(x,R.types[0]));return {kind:"mc",t:"mc",html:`<pre class="sqlcode">${sqlHL(model)}</pre>${dbTableHTML(tb,{sm:true})}`,q:"What is the result of this query?",a,opts:shuffle([a,...w]),why:`${/COUNT/i.test(model)?"COUNT counts the matching records":"SUM adds up the values in the matching records"}: the answer is ${a}.`}}
  const n=R.rows.length,a=String(n),w=uq([n+1,n-1,n+2,n-2,R.T.r.length].filter(x=>x!==n&&x>=0).map(String)).slice(0,3);
  return {kind:"mc",t:"mc",html:`<pre class="sqlcode">${sqlHL(model)}</pre>${dbTableHTML(tb,{sm:true})}`,q:"How many records will this query return?",a,opts:shuffle([a,...w]),why:`${n} record${n===1?" matches":"s match"} the condition.`}})};
const DBPK=[["A library's Books table",["BookID","Title","Author","Genre"],"BookID","Two books can have the same title, author or genre, but every BookID is different."],["A garage's Cars table",["Registration","Make","Colour","OwnerName"],"Registration","Every car has its own registration number plate, but makes, colours and owner names can repeat."],["A school's Students table",["StudentID","FirstName","Surname","YearGroup"],"StudentID","Several students can share a name or year group, but each has a unique StudentID."],["A hospital's Patients table",["PatientNumber","Name","DateOfBirth","Doctor"],"PatientNumber","Patients can share names, birthdays and doctors, but not a patient number."],["A shop's Products table",["Barcode","ProductName","Price","Category"],"Barcode","Each product has its own barcode. Prices and categories repeat."],["A gym's Members table",["MemberID","Surname","Town","Age"],"MemberID","Members can share a surname, town or age, but every MemberID is different."],["An airline's Passengers table",["PassportNumber","FirstName","Surname","Seat"],"PassportNumber","Every passport number is unique. Names repeat, and seat numbers repeat on different flights."]];
GEN.dbpk=function(){return shuffle(DBPK).slice(0,5).map(([t,f,a,why])=>({kind:"mc",t:"mc",q:`${t} has these fields. Which is the most suitable primary key?`,a,opts:shuffle(f.slice()),why}))};
const DBTQ=[["Surname","Patel","Text/alphanumeric"],["Postcode","SW1A 1AA","Text/alphanumeric"],["Phone number","07700 900123","Text/alphanumeric"],["Number of siblings","2","Integer"],["Height in metres","1.65","Real"],["Price","4.99","Real"],["Has paid?","Yes or No","Boolean"],["Date of birth","14/02/2011","Date/time"],["Gender","M or F","Character"],["Grade","B","Character"],["Quantity in stock","35","Integer"],["Email address","sam@example.com","Text/alphanumeric"],["Owns a pet?","TRUE or FALSE","Boolean"],["Appointment time","09:30","Date/time"],["Year group","10","Integer"],["Temperature","21.5","Real"],["Shoe size","5.5","Real"],["Number of goals scored","3","Integer"]];
GEN.dbtype=function(){return shuffle(DBTQ).slice(0,8).map(([f,ex,a])=>({kind:"mc",t:"mc",q:`What is the most suitable data type for this field? ${f} (e.g. ${ex})`,a,opts:shuffle(DBTY.slice()).slice(0,6),why:a==="Text/alphanumeric"&&/\d/.test(ex)?"It has digits, but it's not used for maths (and may have spaces or a leading 0), so it's text.":`${f} should be ${a.toLowerCase()}.`}))};
const DBCK=[["A year group must be between 7 and 13","Range check"],["A password must be at least 8 characters long","Length check"],["The surname field can't be left empty","Presence check"],["A date of birth must be entered as dd/mm/yyyy","Format check"],["An age must be a whole number, not text","Type check"],["The last digit of a barcode is calculated from the other digits","Check digit"],["A mark must be from 0 to 100","Range check"],["A postcode must be in the pattern of letters and digits","Format check"],["A phone number must be exactly 11 digits long","Length check"],["An email address must be entered before the form can be sent","Presence check"],["A price must be a number","Type check"],["The final digit of an ISBN detects a mistyped number","Check digit"]];
GEN.dbcheck=function(){const C=["Range check","Length check","Presence check","Format check","Type check","Check digit"];return shuffle(DBCK).slice(0,8).map(([q,a])=>({kind:"mc",t:"mc",q:`Which validation check is this? ${q}.`,a,opts:shuffle([a,...shuffle(C.filter(x=>x!==a)).slice(0,3)]),why:`This is a ${a.toLowerCase()}.`}))};
GEN.dbpartsq=function(){const T=DBT.Dogs,h=dbTableHTML("Dogs",{sm:true}),f=dbR(T.f.slice(1))[0],r=dbR(T.r);
  return shuffle([{q:`In the Dogs table, what is "${f}"?`,a:"A field",opts:["A field","A record","A table","A primary key"],why:"Each column is a field: one piece of information about each dog."},
   {q:`What is the row of data about ${r[1]} called?`,a:"A record",opts:["A record","A field","A table","A data type"],why:"All the data about one item (one dog) is a record."},
   {q:"How many records are in the Dogs table?",a:String(T.r.length),opts:shuffle(["8","7","9","56"]),why:`There are ${T.r.length} rows, one for each dog.`},
   {q:"How many fields are in the Dogs table?",a:String(T.f.length),opts:shuffle(["7","8","6","1"]),why:`There are ${T.f.length} columns: ${T.f.map(x=>x[0]).join(", ")}.`},
   {q:"Which field is the primary key?",a:"DogID",opts:shuffle(["DogID","Name","Breed","Age"]),why:"DogID is unique for every dog. Two dogs could share a name, breed or age."},
   {q:"Why can't Breed be the primary key?",a:"Several dogs have the same breed",opts:shuffle(["Several dogs have the same breed","It's text","It's too long","It's not the first field"]),why:"A primary key must be unique for every record."}]).map(x=>Object.assign({kind:"mc",t:"mc",html:h},x))};
const PCK=new Set("DECLARE CONSTANT ARRAY OF INTEGER REAL STRING CHAR BOOLEAN FOR TO STEP NEXT INPUT OUTPUT IF THEN ELSE ENDIF WHILE DO ENDWHILE REPEAT UNTIL TRUE FALSE AND OR NOT CASE OTHERWISE ENDCASE PROCEDURE ENDPROCEDURE FUNCTION ENDFUNCTION RETURN RETURNS CALL MOD DIV OPENFILE READFILE WRITEFILE CLOSEFILE READ WRITE".split(" "));
const PYK=new Set("for in range print input int float str if elif else while def return True False and or not len append".split(" "));
function codeHL(src,py){const e=s=>s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
  return src.replace(/("[^"]*"|'[^']*')|(\/\/.*$|#.*$)|([A-Za-z_]\w*)|(\d+(?:\.\d+)?)|([^"'\/#A-Za-z_\d]+|\/)/gm,(m,s,c,w,n,o)=>s?`<span class="cs">${e(s)}</span>`:c?`<span class="cc">${e(c)}</span>`:w?((py?PYK:PCK).has(w)?`<span class="ck">${w}</span>`:w):n?`<span class="cn">${n}</span>`:e(o))}
function pcBox(code,o={}){const lines=code.replace(/\s+$/,"").split("\n");let n=0;
  return `<div class="pcbox${o.py?" py":""}">${o.t?`<div class="pch">${o.py?"🐍 ":""}${o.t}</div>`:""}<pre class="pcb">${lines.map((l,i)=>{const cm=/^\s*(\/\/|#)/.test(l)&&!o.nums;const num=cm?"":++n;return `<span class="pcl${o.hl===i?" cur":""}"><i>${num}</i>${codeHL(l,o.py)||" "}</span>`}).join("")}</pre></div>`}
function pcDecorate(el){if(el.dataset.done)return;el.dataset.done=1;const w=document.createElement("div");w.innerHTML=pcBox(el.textContent.replace(/^\n/,""),{t:el.dataset.t,py:el.classList.contains("py")});el.replaceWith(w.firstChild)}

