 total:{t:"Total and average",a:TEMPS,name:"Temps",code:`Total ← 0\nFOR Day ← 1 TO 7\n   Total ← Total + Temps[Day]\nNEXT Day\nAverage ← Total / 7\nOUTPUT "Average: ", Average`,run:(V,A,out,s)=>{V.Total=0;s(0);for(let d=1;d<=7;d++){V.Day=d;s(1);V.Total+=A[d-1];s(2,d-1);s(3)}V.Average=Math.round(V.Total/7*100)/100;s(4);out.push("Average: "+V.Average);s(5)}},
