const PSID=[["TotalScore",1,"It starts with a letter and uses only letters."],["2ndPlace",0,"It starts with a digit."],["first name",0,"It contains a space."],["Café",0,"It contains an accented letter."],["Player1",1,"Letters followed by a digit is fine."],["OUTPUT",0,"OUTPUT is a keyword."],["Price£",0,"It contains a symbol."],["NumberOfLives",1,"Letters only, and it describes the data."],["High-Score",0,"It contains a hyphen."],["DateOfBirth",1,"Letters only, and it describes the data."],["WHILE",0,"WHILE is a keyword."],["Item7",1,"It starts with a letter."],["7Item",0,"It starts with a digit."],["Max Speed",0,"It contains a space."],["Total$",0,"It contains a symbol."],["Level2Boss",1,"Letters and digits, starting with a letter."]];
