  for(let i=0;i<2;i++){const t=PSR(10,35),r=lgPick([true,false]),code=`DECLARE Temp : INTEGER\nDECLARE Raining : BOOLEAN\nTemp ← ${t}\nRaining ← ${r?"TRUE":"FALSE"}\nIF Temp > 25 AND Raining = FALSE\n  THEN\n    OUTPUT "Go to the beach"\n  ELSE\n    OUTPUT "Stay at home"\nENDIF`;const a=psOut(code);qs.push({kind:"mc",t:"mc",html:pcBox(code),q:"What is output?",a,opts:["Go to the beach","Stay at home"],why:`Temp > 25 is ${t>25?"TRUE":"FALSE"} and Raining = FALSE is ${!r?"TRUE":"FALSE"}. AND needs both to be TRUE.`})}
