const PSVQ=[["Range check","Age must be between 13 and 100"],["Presence check","A name must be entered"],["Length check","A password must be 8 to 20 characters long"],["Format check","An ID must be 3 letters followed by 4 digits"],["Type check","An age must be a whole number"],["Check digit","The last digit of a barcode is calculated from the others"]];
GEN.psval=function(){const qs=shuffle(PSVQ).slice(0,4).map(([a,d])=>({kind:"mc",t:"mc",q:`Which validation check is this? ${d}.`,a,opts:shuffle(PSVQ.map(x=>x[0])).slice(0,6),why:`This is a ${a.toLowerCase()}.`}));
  for(let i=0;i<4;i++){const lo=lgPick([1,5,10,13]),hi=lo+lgPick([20,50,90]),v=lgPick([lo-1,lo,hi,hi+1,PSR(lo,hi),PSR(hi+2,hi+40)]),ok=v>=lo&&v<=hi;
    qs.push({kind:"mc",t:"mc",html:pcBox(`IF Value >= ${lo} AND Value <= ${hi}\n  THEN\n    OUTPUT "Accepted"\n  ELSE\n    OUTPUT "Rejected"\nENDIF`),q:`What is output if Value is ${v}?`,a:ok?"Accepted":"Rejected",opts:["Accepted","Rejected"],why:`${v} is ${ok?"":"not "}between ${lo} and ${hi}${v===lo||v===hi?" (the boundary values are included, because of >= and <=)":""}.`})}
  return shuffle(qs)};
const psFind=(V,ty,re)=>[...V.values()].filter(x=>!x.arr&&(ty?((x.ty||x.inf)===ty||(ty==="NUM"&&["INTEGER","REAL"].includes(x.ty||x.inf))):true)&&(!re||re.test(x.name)));
const psNeed=(lab,ty,re,eg)=>({l:lab,f:V=>{const ok=x=>ty==="NUM"?["INTEGER","REAL"].includes(x.ty||x.inf):(x.ty||x.inf)===ty,an=(/^[AEIOU]/.test(ty)?"an ":"a ")+ty,byName=[...V.values()].filter(x=>!x.arr&&re.test(x.name));
  if(byName.length){const x=byName.find(ok)||byName[0];if(!x.ty)return `${x.name} has a value, but it wasn't declared with DECLARE.`;if(!ok(x))return `${x.name} should be ${ty==="NUM"?"INTEGER or REAL":ty}, not ${x.ty}.`;if(x.v===undefined)return `${x.name} is declared, but it hasn't been assigned a value.`;return true}
  return `I couldn't find ${ty==="NUM"?"a number":an} variable with a meaningful name for this, e.g. ${eg}.`}});
const psAllDecl={l:"Every variable is declared with DECLARE",f:V=>{if(!V.size)return "There are no variables yet.";const u=[...V.values()].filter(x=>!x.ty&&!x.cst);return u.length?`${u.map(x=>x.name).join(", ")} ${u.length>1?"weren't":"wasn't"} declared.`:true}};
