Object.assign(PSPROGS.chusername,{io:1,check:[psIOt("Priya, Shah, 10 → SHAP10",["Priya","Shah",10],o=>o.join("").replace(/\s/g,"").includes("SHAP10")?true:`Expected SHAP10 in the output, but your program output: "${o.join(" ").slice(0,140)}"`),psIOt("Tom, Baker, 11 → BAKT11",["Tom","Baker",11],o=>o.join("").replace(/\s/g,"").includes("BAKT11")?true:`Expected BAKT11 in the output. Check you use UCASE and SUBSTRING. Your program output: "${o.join(" ").slice(0,140)}"`),psIOt("Works with lower-case input: zara, smith, 9 → SMIZ9",["zara","smith",9],o=>o.join("").replace(/\s/g,"").includes("SMIZ9")?true:"Use UCASE so the username is in capitals, even if the name is typed in lower case.")]});
const psCoin=o=>{const tl=o.filter(x=>/^\s*(heads|tails)\s*$/i.test(x));return {tl,h:tl.filter(x=>/heads/i.test(x)).length}};
Object.assign(PSPROGS.chcoin,{io:1,check:[{l:"Outputs Heads or Tails exactly 10 times",f:(V,io)=>{const {tl}=psCoin(io([]));return tl.length===10?true:`Your program output Heads or Tails ${tl.length} time${tl.length===1?"":"s"}. Each toss should output just the word Heads or Tails.`}},
  {l:"Both Heads and Tails can come up",f:(V,io)=>{let H=0,T=0;for(let i=0;i<6;i++){const {tl,h}=psCoin(io([]));H+=h;T+=tl.length-h}return H&&T?true:"Use RANDOM() so each toss can be either Heads or Tails, e.g. IF RANDOM() < 0.5."}},
  {l:"Outputs the correct number of heads at the end",f:(V,io)=>{for(let i=0;i<5;i++){const o=io([]),{h}=psCoin(o),last=o.filter(x=>!/^\s*(heads|tails)\s*$/i.test(x)).join(" ");if(psNums([last],[h])!==true)return `There were ${h} heads, but the count you output was "${last||"nothing"}". Count the heads with a variable, starting at 0.`}return true}}]});
function psWalk(B,fn){(B||[]).forEach(s=>{fn(s);[s.th,s.el,s.body].forEach(b=>b&&psWalk(b,fn));if(s.cl)s.cl.forEach(c=>psWalk(c.body,fn));if(s.other)psWalk(s.other.body,fn)})}
function psLocalOf(subs,k){for(const u of subs.values()){if(u.params.some(p=>p.n.toLowerCase()===k))return u.name;let f=false;psWalk(u.body,s=>{if(s.k==="decl"&&s.names.some(n=>n.toLowerCase()===k))f=true});if(f)return u.name}return null}
function psExprs(s){return [s.e,s.cond,s.on,s.from,s.to,s.step,...(s.items||[]),...(s.c?[s.c]:[])].filter(Boolean)}
function psCallsIn(e,out){if(!e||typeof e!=="object")return;if(e.k==="call")out.push(e.n.toLowerCase());[e.a,e.b].forEach(x=>psCallsIn(x,out));(e.idx||[]).forEach(x=>psCallsIn(x,out));(e.args||[]).forEach(x=>psCallsIn(x,out))}
function psIds(prog){const ids=[],forv=new Set(),all=new Set();const add=(n,k)=>{if(!all.has(n.toLowerCase())){all.add(n.toLowerCase());ids.push({n,k})}};
  const visit=s=>{if(s.k==="decl")s.names.forEach(n=>add(n,s.dims?"array":"variable"));if(s.k==="const")add(s.n,"constant");if(s.k==="for")forv.add(s.v.toLowerCase());if((s.k==="set"||s.k==="input")&&!forv.has(s.tg.n.toLowerCase()))add(s.tg.n,"variable")};
  psWalk(prog,visit);for(const u of prog.subs.values()){add(u.name,u.kind.toLowerCase());u.params.forEach(p=>add(p.n,"parameter"));psWalk(u.body,visit)}
  return ids.filter(x=>!forv.has(x.n.toLowerCase())||x.k!=="variable")}
const psComments=src=>src.split("\n").filter(l=>/^(?:[^"'“”‘’]|"[^"]*"|'[^']*')*\/\//.test(l)&&l.replace(/^.*?\/\//,"").trim().length>2).length;
function psRunSt(src,ins){const st={V:new Map(),out:[],inq:(ins||[]).map(String),steps:0,max:20000};const g=psExec(psParse(src),st);let r;while(!(r=g.next()).done){if(r.value===-1)throw new PsErr(-1,"Your program asked for more inputs than the task gives it. Check the number of INPUT lines.")}return st}
const mtShort={l:"Meaningful identifiers: no single letters or names like x1",f:(V,io,src)=>{const bad=psIds(psParse(src)).filter(x=>x.n.length<2||/^[a-z]\d+$/i.test(x.n)||/^(var|variable|num|number|stuff|data|value|thing)\d*$/i.test(x.n));return bad.length?`Rename ${bad.map(x=>`${x.n} (${x.k})`).join(", ")} so ${bad.length>1?"each name describes":"the name describes"} what it stores or does.`:true}};
const mtComm=(n,eg)=>({l:n>1?`At least ${n} helpful comments`:"A comment explaining your code",f:(V,io,src)=>{const c=psComments(src);return c>=n?true:`You have ${c} comment${c===1?"":"s"}. Start a comment with //, e.g. // ${eg}`}});
