 mtfunc2:{t:"A validation function",inputs:true,code:`// Asks for a mark until it's from 0 to 100, then returns it\nFUNCTION GetValidMark() RETURNS INTEGER\n    DECLARE Mark : INTEGER\n    OUTPUT "Enter a mark from 0 to 100"\n    INPUT Mark\n    WHILE Mark < 0 OR Mark > 100 DO\n        OUTPUT "Invalid. Enter a mark from 0 to 100"\n        INPUT Mark\n    ENDWHILE\n    RETURN Mark\nENDFUNCTION\n\n// Main program\nDECLARE Test1, Test2 : INTEGER\nTest1 ← GetValidMark()\nTest2 ← GetValidMark()\nOUTPUT "Average: ", (Test1 + Test2) / 2`},
