const VVQ=[["Making sure a mark is between 0 and 100","Range check"],["Making sure a password has at least 8 characters","Length check"],["Making sure an age is a whole number, not text","Type check"],["Making sure the email field hasn't been left empty","Presence check"],["Making sure a car registration matches the pattern AB12 CDE","Format check"],["Making sure a barcode was scanned correctly, using its last digit","Check digit"],["Asking the user to type their new email address twice","Double entry check"],["Showing the user their details and asking them to confirm they're correct","Visual check"],["Making sure a phone number is exactly 11 digits long","Length check"],["Making sure a date of birth is in the form DD/MM/YYYY","Format check"],["Making sure the number of tickets is from 1 to 8","Range check"],["Making sure a price is a number","Type check"]];
GEN.vvq=function(){const all=uq(VVQ.map(x=>x[1]));return shuffle(VVQ).slice(0,8).map(([d,a])=>({kind:"mc",t:"mc",q:`Which check is this? ${d}.`,a,opts:shuffle([a,...shuffle(all.filter(x=>x!==a)).slice(0,3)]),why:/Double|Visual/.test(a)?`This is verification: it checks the data was entered accurately. ${a}.`:`This is validation: an automatic check that the data is reasonable. ${a}.`}))};
GEN.tdtype=function(){const qs=[];for(let k=0;k<6;k++){const sc=lgPick(TDS),lo=sc.lo,hi=sc.hi;const kind=k%3;
  if(kind===0){const v=PSR(lo+1,hi-1);qs.push({kind:"mc",t:"mc",q:`${sc.what[0].toUpperCase()+sc.what.slice(1)} must be from ${lo} to ${hi}. What type of test data is ${v}?`,a:"Normal",opts:["Normal","Abnormal","Extreme","Boundary"],why:`${v} is inside the range and isn't at either end, so it's normal data.`})}
  else if(kind===1){const v=lgPick([hi+PSR(5,40),lo-PSR(5,20),sc.eg]);qs.push({kind:"mc",t:"mc",q:`${sc.what[0].toUpperCase()+sc.what.slice(1)} must be from ${lo} to ${hi}. What type of test data is ${v}?`,a:"Abnormal",opts:["Normal","Abnormal","Extreme","Boundary"],why:`${v} should be rejected and isn't next to the limits, so it's abnormal data.`})}
  else{const up=Math.random()<.5,a=up?`${hi} and ${hi+1}`:`${lo} and ${lo-1}`,w=up?[`${hi-1} and ${hi}`,`${hi+1} and ${hi+2}`,`${lo} and ${hi}`]:[`${lo} and ${lo+1}`,`${lo-2} and ${lo-1}`,`${lo} and ${hi}`];qs.push({kind:"mc",t:"mc",q:`${sc.what[0].toUpperCase()+sc.what.slice(1)} must be from ${lo} to ${hi}. Which pair is boundary data for the ${up?"upper":"lower"} limit?`,a,opts:shuffle([a,...w]),why:`Boundary data is the ${up?"largest":"smallest"} accepted value (${up?hi:lo}) and the ${up?"smallest":"largest"} rejected value next to it (${up?hi+1:lo-1}).`})}}
  qs.push({kind:"mc",t:"mc",q:"Which is extreme data for a mark that must be from 0 to 100?",a:"100",opts:["100","101","50","-1"],why:"Extreme data is the largest or smallest acceptable value: 0 or 100."});return qs};
const ERRQ=[["The program won't run because OUTPUT is spelt OUPTUT","Syntax error"],["A program that should output the average divides the total by the wrong number","Logic error"],["The program crashes when it tries to divide by zero","Runtime error"],["ENDIF is missing at the end of an IF statement","Syntax error"],["IF Age > 18 is used when 18-year-olds should be accepted","Logic error"],["The program crashes when it tries to use Names[11] in an array of 10 items","Runtime error"],["A loop that should run 10 times runs 9 times","Logic error"],["A closing bracket is missing","Syntax error"]];
