function lgTTask(q,r){const done=r!==undefined;if(AQ.ttk!==AQ.k||!AQ.tt){AQ.tt=q.rows.map(()=>-1);AQ.ttk=AQ.k}const g=done?String(AQ.typed):"";
  return `<p class="eyebrow">${q.prompt||"Complete the truth table"}</p>${q.html}
  <div class="tscroll"><table class="pvt lgtbl lgtt"><tr>${q.ins.map(n=>`<th>${n}</th>`).join("")}<th class="lgx">X</th></tr>${q.rows.map((row,i)=>`<tr>${[...row].map(b=>`<td>${b}</td>`).join("")}<td class="lgx">${done?`<span class="lgc ${g[i]===q.ans[i]?"right":"wrong"}">${g[i]}${g[i]!==q.ans[i]?` <small>should be ${q.ans[i]}</small>`:""}</span>`:`<button class="lgcell${AQ.tt[i]<0?" unset":""}" data-act="att" data-i="${i}" aria-label="Output for row ${i+1}, ${[...row].map((b,j)=>q.ins[j]+" = "+b).join(", ")}: ${AQ.tt[i]<0?"not set":AQ.tt[i]}">${AQ.tt[i]<0?"?":AQ.tt[i]}</button>`}</td></tr>`).join("")}</table></div>
  ${done?"":`<p class="vfoot" style="margin:0">Click each output cell to set it to 0 or 1.</p>${AQ.err?`<p class="msg bad" style="margin:0">${AQ.err}</p>`:""}<button class="btn primary" data-act="atts">Check my table</button>`}`}
ACT_TYPES.logic={
 ask:(q,r)=>q.kind==="tt"?lgTTask(q,r):ACT_TYPES.mixed.ask(q,r),
 valid:(q,g)=>q.kind==="typed"?ACT_TYPES.typed.valid(q,g):"",
 check:(q,g)=>q.kind==="tt"?g===q.ans:ACT_TYPES.mixed.check(q,g),
 right:q=>q.kind==="tt"?"Correct! Every row of the truth table is right.":ACT_TYPES.mixed.right(q),
 wrong:q=>q.kind==="tt"?`Not quite. Reading from the top, the output column should be <b class="mono">${q.ans.split("").join(" ")}</b>. The red cells show the rows you got wrong.`:ACT_TYPES.mixed.wrong(q),
 review:w=>w.kind==="tt"?`<span>Truth table: ${esc(w.title)}</span><span>You wrote <b class="mono">${String(w.given).split("").join(" ")}</b>. Answer: <b class="mono">${w.ans.split("").join(" ")}</b></span>`:ACT_TYPES.mixed.review(w)};
function dbSqlAsk(q,r){const done=r!==undefined;if(AQ.sqk!==AQ.k){AQ.sqk=AQ.k;AQ.sqlv="";AQ.sqlprev=""}
  let after="";if(done){const g=String(AQ.typed);let mine;try{const R=sqlRun(g);mine=sqlTable(R.cols,R.types,R.rows,{sm:true})}catch(e){mine=`<p class="msg bad" style="margin:0">⚠️ ${esc(String(e))}</p>`}
    const B=sqlRun(q.model);after=`<div class="sqlpair"><div><span class="eyebrow">Your result</span>${mine}</div><div><span class="eyebrow">Correct result</span>${sqlTable(B.cols,B.types,B.rows,{sm:true})}</div></div>`}
  return `<p class="eyebrow">Write an SQL query</p><p class="qdef">${esc(q.task)}</p>${dbTableHTML(q.tb,{sm:true})}
  <label class="vfoot" for="act-sql">Your query</label><textarea id="act-sql" class="sqlin" rows="3" spellcheck="false" autocapitalize="off" autocomplete="off"${done?" disabled":""}>${esc(done?String(AQ.typed):AQ.sqlv||"")}</textarea>
  ${done?after:`<div class="row-btns"><button class="btn small" data-act="asqlrun">▶ Test my query</button><button class="btn primary small" data-act="asql">Check my answer</button></div>${AQ.err?`<p class="msg bad" style="margin:0">${AQ.err}</p>`:""}${AQ.sqlprev?`<div class="sqlres">${AQ.sqlprev}</div>`:""}`}`}
ACT_TYPES.db={
 ask:(q,r)=>q.kind==="sqlw"?dbSqlAsk(q,r):ACT_TYPES.mixed.ask(q,r),
 valid:(q,g)=>q.kind==="typed"?ACT_TYPES.typed.valid(q,g):"",
 check:(q,g)=>q.kind==="sqlw"?dbSameResult(g,q.model)[0]:ACT_TYPES.mixed.check(q,g),
 right:q=>q.kind==="sqlw"?"Correct! Your query gives exactly the right result.":ACT_TYPES.mixed.right(q),
 wrong:q=>{if(q.kind!=="sqlw")return ACT_TYPES.mixed.wrong(q);const [,m]=dbSameResult(String(AQ.typed),q.model);return `Not quite. ${esc(m||"")}<br>One correct answer is:<pre class="sqlcode" style="margin:6px 0 0">${sqlHL(q.model)}</pre>`},
 review:w=>w.kind==="sqlw"?`<span>${esc(w.task)}</span><span>You wrote <b class="mono">${esc(String(w.given))}</b>. One answer: <b class="mono">${esc(w.model)}</b></span>`:ACT_TYPES.mixed.review(w)};
function actAnswer(l,a,given){const q=AQ.items[AQ.k];AQ.typed=given;
  const ok=ACT_TYPES[a.type||a.gen].check(q,given);AQ.res[AQ.k]=ok;
  if(!ok)AQ.wrong.push(Object.assign({},q,{given}));actCard(l,a);const nx=document.querySelector('[data-act="anext"]');if(nx)nx.focus()}
function actFinish(){const n=AQ.res.filter(Boolean).length,t=AQ.items.length;let o=actStats(S.acts[AQ.key]);
  o=o||{attempts:0,correct:0,total:0,bestN:0,qn:t,hist:[]};
  o.attempts++;o.correct+=n;o.total+=t;o.lastN=n;o.bestN=Math.max(o.bestN,n);o.qn=t;o.date=new Date().toISOString();
  o.best=Math.round(o.bestN/t*100);o.last=Math.round(n/t*100);
  o.hist.push({date:o.date,n,wrong:AQ.wrong});if(o.hist.length>20)o.hist.shift();
  S.acts[AQ.key]=o;save()}

function lstart(l){LQ={id:l.id,k:0,right:0,picked:null,items:shuffle(l.q).map(([q,a,...w])=>({q,a,opts:shuffle([a,...w])}))}}
function lfinish(l){const pct=Math.round(LQ.right/LQ.items.length*100),o=S.lessons[l.id];
  /* qs: the latest try question by question (question, answer, what was chosen), for the teacher's view */
  S.lessons[l.id]={best:Math.max(pct,o?o.best:0),last:pct,attempts:(o?o.attempts:0)+1,date:new Date().toISOString(),qs:LQ.items.map(it=>({q:it.q,a:it.a,g:it.given==null?null:it.given}))};save()}

/* wrap each "Step n" line and the examples under it in its own block */
function groupSteps(root){
  root.querySelectorAll(".theory .stepline").forEach(s=>{
    if(s.parentElement.classList.contains("stepblock"))return;
    const box=document.createElement("div");box.className="stepblock";
    s.before(box);box.append(s);
    let n=box.nextElementSibling;
    while(n&&!n.matches(".stepline,h2,h3,.callout,.placeholder,section,.mpanel")){const nx=n.nextElementSibling;box.append(n);n=nx}
  });
}

