    g+=`<rect class="grp${on("cu")}" x="${L.cu[0]}" y="${L.cu[1]}" width="${L.cu[2]}" height="${L.cu[3]}" rx="8"/><text class="rl" x="${L.cu[0]+8}" y="${L.cu[1]+20}">CONTROL UNIT</text>`;
