    for(let k=0;k<16;k++){const [x,y,w,h]=cell(L,k),v=S.mem[k],ins=k<prog.n;g+=`<rect class="${ins?"ins":"dat"}${on("m"+k)}" x="${x}" y="${y}" width="${w}" height="${h}" rx="5" style="${on("m"+k)?"":"stroke:var(--line)"}"/><text class="cl" x="${x+6}" y="${y+13}">${p2(k)}</text><text class="cv" x="${x+w-8}" y="${y+h/2+6}" text-anchor="end">${ins?p3(v):v}</text>${ins?`<text class="cm" x="${x+6}" y="${y+h-6}">${lmcDecode(v).m}</text>`:""}`}
