  const reset=c=>{cap=c||8;ram=[{id:"os",u:0}];vm=[];t=1;swaps=0;slow=0;hot=null;draw("The operating system is loaded into RAM when the computer starts. Click a program to open it.")};
  const used=()=>ram.reduce((s,x)=>s+A[x.id][2],0);
  const draw=msg=>{const free=cap-used(),px=200/cap;
    el.querySelector(".vmapps").innerHTML=APPS.filter(a=>a[0]!=="os").map(([id,n,sz])=>{const inR=ram.some(x=>x.id===id),inV=vm.some(x=>x.id===id);return `<button class="btn small${inR?" on":inV?" vm":""}" data-vm="${id}">${inR?"Use":inV?"Switch to":"Open"} ${n} <small>(${sz} GB)</small></button>`}).join("");
    el.querySelector(".vmram").innerHTML=(free>0?`<div class="vmslot free" style="height:${free*px}px">free space · ${free} GB</div>`:"")+ram.slice().reverse().map(x=>`<div class="vmslot${x.id===hot?" hot":""}" style="height:${A[x.id][2]*px}px;background:${A[x.id][3]}">${A[x.id][1]} · ${A[x.id][2]} GB${x.id!=="os"?` <button class="vmx" data-vmc="${x.id}" aria-label="Close ${A[x.id][1]}">✕</button>`:""}</div>`).join("");
    el.querySelector(".vmswap").innerHTML=vm.length?vm.map(x=>`<div class="vmslot${x.id===hot?" hot":""}" style="height:28px;background:${A[x.id][3]};opacity:.85">${A[x.id][1]} · ${A[x.id][2]} GB <button class="vmx" data-vmc="${x.id}" aria-label="Close ${A[x.id][1]}">✕</button></div>`).join(""):`<span class="vfoot">Empty</span>`;
    el.querySelector("#vm-cap").textContent=`${used()} of ${cap} GB used`;
    el.querySelector(".vmlog").innerHTML=msg;el.querySelector(".vmstats").innerHTML=`<span>Swaps to and from virtual memory <b>${swaps}</b></span><span>Time spent waiting on slow storage <b>${slow}</b> s</span>`;
    el.querySelectorAll("[data-vmcap]").forEach(b=>b.setAttribute("aria-pressed",+b.dataset.vmcap===cap))};
  const makeSpace=(need,keep)=>{const out=[];while(cap-used()<need){const c=ram.filter(x=>x.id!=="os"&&x.id!==keep).sort((a,b)=>a.u-b.u)[0];if(!c)break;ram=ram.filter(x=>x!==c);vm.push(c);out.push(A[c.id][1]);swaps++;slow+=2}return out};
