  const y=v;if(y<1000)return `${y<10?y.toFixed(1):Math.round(y)} years`;const W=[[1e3,"thousand"],[1e6,"million"],[1e9,"billion"],[1e12,"trillion"]];let w=W[0];for(const x of W)if(y>=x[0])w=x;
