function netDemo(el){
  const N={S:[45,130],A:[175,55],B:[175,205],C:[305,130],D:[435,55],E:[435,205],T:[565,130]};
  const edges=[["S","A"],["S","B"],["A","C"],["B","C"],["A","D"],["B","E"],["C","D"],["C","E"],["D","T"],["E","T"]];
  const routes=[["S","A","D","T"],["S","B","E","T"],["S","A","C","E","T"],["S","B","C","D","T"],["S","A","C","D","T"]];
  const still=matchMedia("(prefers-reduced-motion: reduce)").matches;let raf=0,state=null;
  el.innerHTML=`<div class="row-btns"><button class="btn primary small" data-net="send">Send 5 packets</button><button class="btn small" data-net="lose">Send, but lose one</button></div>
   <svg viewBox="0 0 610 260" role="img" aria-label="A network of routers between a sender and a receiver, with numbered packets travelling along different routes"><g class="edges">${edges.map(([a,b])=>`<line x1="${N[a][0]}" y1="${N[a][1]}" x2="${N[b][0]}" y2="${N[b][1]}" stroke="var(--line)" stroke-width="4"/>`).join("")}</g>
   ${Object.entries(N).map(([k,[x,y]])=>k==="S"||k==="T"?`<g><rect x="${x-34}" y="${y-24}" width="68" height="48" rx="8" fill="var(--surface)" stroke="var(--ink)" stroke-width="2.5"/><text x="${x}" y="${y+5}" text-anchor="middle" font-size="13" font-weight="700" fill="var(--ink)" font-family="var(--body)">${k==="S"?"Sender":"Receiver"}</text></g>`:`<g><circle cx="${x}" cy="${y}" r="20" fill="var(--sunk)" stroke="var(--muted)" stroke-width="2"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="10" fill="var(--muted)" font-family="var(--mono)">router</text></g>`).join("")}
   <g class="pks"></g></svg>
   <div class="netlog"><div><span class="eyebrow">Arrived in this order</span><div class="pkrow" id="net-arr"><span class="vfoot">Press a button to send.</span></div></div><div><span class="eyebrow">Rebuilt in order</span><div class="pkrow" id="net-sorted"></div></div></div><p class="vfoot" id="net-msg"></p>`;
  const pts=r=>r.map(k=>N[k]),len=(a,b)=>Math.hypot(b[0]-a[0],b[1]-a[1]);
  const posAt=(path,d)=>{for(let i=0;i<path.length-1;i++){const L=len(path[i],path[i+1]);if(d<=L){const t=d/L;return [path[i][0]+(path[i+1][0]-path[i][0])*t,path[i][1]+(path[i+1][1]-path[i][1])*t]}d-=L}return path[path.length-1]};
  const total=path=>path.slice(1).reduce((s,p,i)=>s+len(path[i],p),0);
  const chip=(n,cls="")=>`<span class="pkchip ${cls}"><small>packet</small>${n}</span>`;
  const start=lose=>{cancelAnimationFrame(raf);const rs=shuffle(routes.slice());
    const pk=rs.map((r,i)=>({n:i+1,path:pts(r),speed:90+Math.random()*140,t0:i*.2,done:false,lost:lose&&i===2}));
    state={pk,arr:[],lose,resent:false,t:performance.now()};el.querySelector("#net-arr").innerHTML="";el.querySelector("#net-sorted").innerHTML="";el.querySelector("#net-msg").textContent="";
    if(still){pk.forEach(p=>{p.done=true});const order=pk.filter(p=>!p.lost).sort((a,b)=>total(a.path)/a.speed+a.t0-(total(b.path)/b.speed+b.t0)).map(p=>p.n);state.arr=order;finish();return}
    raf=requestAnimationFrame(tick)};
  const tick=now=>{const t=(now-state.t)/1000,g=el.querySelector(".pks");let html="";
    state.pk.forEach(p=>{if(p.done)return;const d=Math.max(0,(t-p.t0))*p.speed,T=total(p.path);
      if(p.lost&&d>T*.55){p.done=true;el.querySelector("#net-msg").textContent=`Packet ${p.n} was lost on the way…`;return}
      if(d>=T){p.done=true;state.arr.push(p.n);el.querySelector("#net-arr").innerHTML=state.arr.map(n=>chip(n)).join("");return}
      const [x,y]=posAt(p.path,d);html+=`<g transform="translate(${x},${y})"><circle r="13" fill="var(--accent)"/><text y="5" text-anchor="middle" font-size="13" font-weight="700" fill="var(--surface)" font-family="var(--mono)">${p.n}</text></g>`});
    g.innerHTML=html;
    if(state.pk.every(p=>p.done)){if(state.lose&&!state.resent){const m=state.pk.find(p=>p.lost);el.querySelector("#net-msg").textContent=`Packet ${m.n} is missing! The receiver asks the sender to send packet ${m.n} again.`;
        state.resent=true;setTimeout(()=>{m.done=false;m.lost=false;m.t0=(performance.now()-state.t)/1000+.2;m.path=pts(["S","B","C","D","T"]);raf=requestAnimationFrame(tick)},1400);return}
      finish();return}
    raf=requestAnimationFrame(tick)};
  const finish=()=>{el.querySelector(".pks").innerHTML="";el.querySelector("#net-arr").innerHTML=state.arr.map(n=>chip(n)).join("");
    el.querySelector("#net-sorted").innerHTML=state.arr.slice().sort((a,b)=>a-b).map(n=>chip(n,"ok")).join("");
    el.querySelector("#net-msg").textContent=`${state.arr.join(", ")===state.arr.slice().sort((a,b)=>a-b).join(", ")?"This time they happened to arrive in order. ":"The packets arrived out of order. "}The receiver used the packet numbers in the headers to put them back in order: the file is rebuilt.${state.lose?" (Packet "+state.pk[2].n+" was resent.)":""}`};
  el.addEventListener("click",e=>{const b=e.target.closest("[data-net]");if(b)start(b.dataset.net==="lose")})}
