function addStepper(el){
  const A=el.dataset.a,B=el.dataset.b,n=Math.max(A.length,B.length),reg=+el.dataset.reg||0;
  const a=A.padStart(n,"0"),b=B.padStart(n,"0");
  const ans=[],cin=[0];
  for(let i=0;i<n;i++){const x=+a[n-1-i],y=+b[n-1-i],c=cin[i],s=x+y+c;ans[i]=s%2;cin[i+1]=s>>1}
  const carryOut=cin[n],steps=1+n+(carryOut?1:0),answer=(carryOut?"1":"")+ans.slice().reverse().join("");
  const pv=i=>2**i;
  let k=0;
  const text=s=>{
    if(s===0)return `Write the first binary number on top of the second, lining up the columns on the right. The answer goes in the bottom row and any carried 1s go in the top row.`;
    if(s<=n){const i=s-1,x=+a[n-1-i],y=+b[n-1-i],c=cin[i],ones=x+y+c;
      let t=`${i===0?"Start with the right-hand column":"Move one column to the left"} (the ${pv(i)}s). Add ${x} + ${y}${c?" + the carried 1":""}. `;
      if(ones===0)t+=`By rule 1, 0 + 0 = 0, so write <b>0</b>.`;
      else if(ones===1)t+=c?`The two 0s don't change anything, so this is just the carried 1. By rule 2, write <b>1</b>.`:`By rule 2, 1 + 0 = 1, so write <b>1</b>.`;
      else if(ones===2)t+=`${c?"The 0 doesn't change anything, so this is 1 + 1. ":""}By rule 3, 1 + 1 = 10, so write <b>0</b> and carry <b>1</b> to the next column.`;
      else t+=`By rule 4, 1 + 1 + 1 = 11, so write <b>1</b> and carry <b>1</b> to the next column.`;
      if(s===steps-1)t+=` The answer is <b class="mono">${answer}</b>.`;
      return t}
    return reg&&n>=reg?`The carried 1 needs a 9th column, but the register only holds ${reg} bits. It doesn't fit, so it's lost. This is an <b>overflow error</b>. The full answer is <b class="mono">${answer}</b>, but the register stores <b class="mono">${ans.slice().reverse().join("")}</b>.`
      :`Finally, all that's left is the carried 1. There's nothing to add it to, so write it in the answer row. The answer is <b class="mono">${answer}</b>.`};
  const draw=()=>{const done=Math.min(k,n),cur=k===0?-1:k-1; // cur column index from right; n means the extra column
    const cols=[...Array(n+1)].map((_,j)=>n-j); // index from right for each displayed column
    const cell=(i,v,cls="")=>`<td class="${cls}${i===cur?" cur":""}">${v}</td>`;
    el.querySelector(".addtbl").innerHTML=
     `<tr><th class="lbl"></th>${cols.map(i=>`<th class="${i===cur?"cur":""}">${i===n&&reg&&n>=reg?"9th bit":pv(i)}</th>`).join("")}</tr>
     <tr><td class="lbl">Carry</td>${cols.map(i=>cell(i,i>0&&i<=done&&cin[i]?"1":"","carry")).join("")}</tr>
     <tr><td class="lbl"></td>${cols.map(i=>cell(i,i<n?a[n-1-i]:"")).join("")}</tr>
     <tr><td class="lbl">+</td>${cols.map(i=>cell(i,i<n?b[n-1-i]:"")).join("")}</tr>
     <tr class="sumrow"><td class="lbl">Answer</td>${cols.map(i=>i<n?cell(i,i<done?ans[i]:"","ans"):cell(i,k>n?"1":"",k>n&&reg&&n>=reg?"ovf":"ans")).join("")}</tr>`;
    el.querySelector(".addexp").innerHTML=`<span class="pill">${k===0?"SET UP":"STEP "+k}</span><span>${text(k)}</span>`;
    el.querySelector("[data-ad=prev]").disabled=k===0;el.querySelector("[data-ad=next]").disabled=k===steps-1;
    el.querySelector(".prog").textContent=`${k+1} of ${steps}`};
  el.innerHTML=`<div class="tscroll"><table class="pvt addtbl"></table></div><div class="addexp" aria-live="polite"></div>
   <div class="addnav"><button class="btn small" data-ad="prev">← Back</button><button class="btn primary small" data-ad="next">Next step →</button><button class="btn small" data-ad="all">Show answer</button><span class="prog"></span></div>`;
  el.addEventListener("click",e=>{const b=e.target.closest("[data-ad]");if(!b)return;const d=b.dataset.ad;
    k=d==="prev"?Math.max(0,k-1):d==="next"?Math.min(steps-1,k+1):steps-1;draw()});
  draw();
}
function spotGame(el){
  const R="6AFC59",W="6CFC59";
  const rounds=[{name:"Hexadecimal",right:R,wrong:W,cls:""},{name:"Binary",right:h2b(R),wrong:h2b(W),cls:" bin"}];
  let k=-1,t0=0,timer=null;const times=[];
  const stop=()=>{clearInterval(timer);timer=null};
  const intro=()=>{el.innerHTML=`<button class="btn primary" data-sp="go" style="align-self:flex-start">Start: hexadecimal round</button>`};
  const show=()=>{const r=rounds[k];
    el.innerHTML=`<div class="spotgrid">
     <div class="spotcard"><span class="eyebrow">Correct ${r.name.toLowerCase()}</span><div class="codeline${r.cls}">${r.right.split("").map(c=>`<span>${c}</span>`).join("")}</div></div>
     <div class="spotcard"><span class="eyebrow">Incorrect ${r.name.toLowerCase()}</span><div class="codeline${r.cls}">${r.wrong.split("").map((c,i)=>`<button data-sp="${c!==r.right[i]?"hit":"miss"}" aria-label="Character ${i+1}: ${c}">${c}</button>`).join("")}</div></div></div>
     <span class="timer" id="sp-t">0.0 seconds</span>`;
    t0=performance.now();stop();timer=setInterval(()=>{const t=el.querySelector("#sp-t");if(t)t.textContent=((performance.now()-t0)/1000).toFixed(1)+" seconds"},100)};
  const done=b=>{stop();const s=(performance.now()-t0)/1000;times[k]=s;
    el.querySelectorAll('[data-sp="hit"]').forEach(x=>x.classList.add("found"));el.querySelectorAll(".codeline button").forEach(x=>x.disabled=true);
    const t=el.querySelector("#sp-t");
    if(k===0){t.innerHTML=`Found it in <b>${s.toFixed(1)} seconds</b>. Now try the same codes in binary.`;
      el.insertAdjacentHTML("beforeend",`<button class="btn primary" data-sp="next" style="align-self:flex-start">Start: binary round</button>`)}
    else{t.innerHTML=`Found it in <b>${s.toFixed(1)} seconds</b>.`;
      el.insertAdjacentHTML("beforeend",`<p class="msg ok">Hexadecimal: ${times[0].toFixed(1)} s &nbsp;·&nbsp; Binary: ${times[1].toFixed(1)} s. ${times[1]>times[0]?"The binary took you longer, even though it's exactly the same data.":"You were quick! Most people take much longer with binary, even though it's the same data."} Changing one hex digit (A to C) changed two bits in the binary.</p>
      <button class="btn" data-sp="again" style="align-self:flex-start">Play again</button>`)}};
  el.addEventListener("click",e=>{const b=e.target.closest("[data-sp]");if(!b)return;const a=b.dataset.sp;
    if(a==="go"||a==="next"){k++;show()}else if(a==="again"){k=-1;times.length=0;intro()}
    else if(a==="hit")done(b);else if(a==="miss"){b.classList.add("miss");setTimeout(()=>b.classList.remove("miss"),400)}});
  intro();
}
