function memDump(el){
  const text="ERROR: Stack overflow in process main.exe",bytes=Array.from(text).map(ch=>ch.charCodeAt(0));let mode="hex";
  el.innerHTML=`<div class="seg" id="dm-seg"><button data-dm="hex" aria-pressed="true">Hexadecimal</button><button data-dm="bin" aria-pressed="false">Binary</button></div><div class="dumpview"><pre id="dm-pre"></pre></div><p class="vfoot" id="dm-note"></p>`;
  const draw=()=>{const per=mode==="hex"?8:4,rows=[];
    for(let i=0;i<bytes.length;i+=per){const row=bytes.slice(i,i+per);
      rows.push(`<span class="off">${(0x7FF4A0+i).toString(16).toUpperCase().padStart(8,"0")}</span>  ${row.map(b=>mode==="hex"?b.toString(16).toUpperCase().padStart(2,"0"):b.toString(2).padStart(8,"0")).join(" ")}  <span class="asc">${esc(String.fromCharCode(...row))}</span>`)}
    el.querySelector("#dm-pre").innerHTML=rows.join("\n");
    el.querySelector("#dm-note").textContent=mode==="hex"?`${bytes.length} bytes shown as hex: ${rows.length} rows. The left column is the memory address and the right column shows the bytes as text.`:`The same ${bytes.length} bytes in binary: ${rows.length} rows, and every value is 8 digits long. Imagine reading a dump of several gigabytes like this.`};
  el.addEventListener("click",e=>{const b=e.target.closest("[data-dm]");if(!b)return;mode=b.dataset.dm;el.querySelectorAll("[data-dm]").forEach(x=>x.setAttribute("aria-pressed",x===b));draw()});
  draw();
}

