    const check=v>=0?`Sign bit is 0, so the number is positive.`:v===-128?`Sign bit is 1, so the number is negative.`:`Check: flip ${b} → ${b.split("").map(x=>x==="1"?"0":"1").join("")}, add 1 → ${bin8(-v)} = ${-v}, so the number is ${v}.`;
    let w;if(v>=0)w=`${v} is positive, so write it in binary as normal:\n${b}`;
